                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            result.append(cells)
    return result


def signature(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return frozenset((r - minr, c - minc) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    templates = {}
    for color in range(2, 10):
        for cells in components(grid, color):
            templates.setdefault(signature(cells), color)
    for cells in components(grid, 1):
        color = templates.get(signature(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out


